SELECT "Motos_2"."Medio" AS "Medio",   SUM("Motos_2"."InversionUS") AS "sum_Calculation_0061002123102817_ok",   CAST(EXTRACT(YEAR FROM "Motos_2"."FECHA") AS BIGINT) AS "yr_FECHA_ok" FROM "Motos_2" WHERE (("Motos_2"."Medio" = 'RADIO') AND (CAST(EXTRACT(YEAR FROM "Motos_2"."FECHA") AS BIGINT) = 2015) AND ("Motos_2"."Categoria" = 'MOTOCICLETAS')) GROUP BY "Motos_2"."Medio",   "yr_FECHA_ok";
